#include <iostream>
#include <cmath>
using namespace std;

int st[100001][20];
int lg[100001];
int n;

void build(int a[]) {
    for (int i = 1; i <= n; i++) st[i][0] = a[i];
    for (int j = 1; (1 << j) <= n; j++)
        for (int i = 1; i + (1 << j) - 1 <= n; i++)
            st[i][j] = min(st[i][j-1], st[i + (1 << (j-1))][j-1]);
    lg[1] = 0;
    for (int i = 2; i <= n; i++) lg[i] = lg[i/2] + 1;
}

int query(int l, int r) {
    int k = lg[r - l + 1];
    return min(st[l][k], st[r - (1 << k) + 1][k]);
}

int main() {
    cin >> n;
    int a[100001];
    for (int i = 1; i <= n; i++) cin >> a[i];
    build(a);
    int q;
    cin >> q;
    while (q--) {
        int l, r;
        cin >> l >> r;
        cout << query(l, r) << endl;
    }
    return 0;
}

#include <iostream>
#include <cmath>
using namespace std;

const int MAXN = 100001;
int a[MAXN];
long long sum[400], tag[400];
int B, bn;

void init(int n) {
    B = sqrt(n);
    bn = (n + B - 1) / B;
    for (int i = 1; i <= n; i++) sum[i / B] += a[i];
}

void rangeAdd(int l, int r, int v) {
    int bl = l / B, br = r / B;
    if (bl == br) {
        for (int i = l; i <= r; i++) { a[i] += v; sum[bl] += v; }
        return;
    }
    for (int i = l; i < (bl+1)*B; i++) { a[i] += v; sum[bl] += v; }
    for (int i = bl+1; i < br; i++) tag[i] += v;
    for (int i = br*B; i <= r; i++) { a[i] += v; sum[br] += v; }
}

long long rangeSum(int l, int r) {
    long long res = 0;
    int bl = l / B, br = r / B;
    if (bl == br) {
        for (int i = l; i <= r; i++) res += a[i] + tag[bl];
        return res;
    }
    for (int i = l; i < (bl+1)*B; i++) res += a[i] + tag[bl];
    for (int i = bl+1; i < br; i++) res += sum[i] + tag[i] * B;
    for (int i = br*B; i <= r; i++) res += a[i] + tag[br];
    return res;
}

int main() {
    int n;
    cin >> n;
    for (int i = 1; i <= n; i++) cin >> a[i];
    init(n);
    int q;
    cin >> q;
    while (q--) {
        int op, l, r, v;
        cin >> op >> l >> r;
        if (op == 1) {
            cin >> v;
            rangeAdd(l, r, v);
        } else {
            cout << rangeSum(l, r) << endl;
        }
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
using namespace std;

int a[100001], cnt[100001], ans[100001];
int curAns;
int B;

struct Query {
    int l, r, id;
    bool operator<(const Query &o) const {
        int bl = l / B, br = o.l / B;
        if (bl != br) return bl < br;
        return (bl & 1) ? r < o.r : r > o.r;
    }
};

void add(int x) {
    if (cnt[a[x]] == 0) curAns++;
    cnt[a[x]]++;
}

void del(int x) {
    cnt[a[x]]--;
    if (cnt[a[x]] == 0) curAns--;
}

int main() {
    int n, q;
    cin >> n >> q;
    B = sqrt(n);
    for (int i = 1; i <= n; i++) cin >> a[i];
    vector<Query> queries(q);
    for (int i = 0; i < q; i++) {
        cin >> queries[i].l >> queries[i].r;
        queries[i].id = i;
    }
    sort(queries.begin(), queries.end());
    int L = 1, R = 0;
    for (auto &qr : queries) {
        while (L > qr.l) add(--L);
        while (R < qr.r) add(++R);
        while (L < qr.l) del(L++);
        while (R > qr.r) del(R--);
        ans[qr.id] = curAns;
    }
    for (int i = 0; i < q; i++)
        cout << ans[i] << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int ch[100001][26];
bool endMark[100001];
int tot;

void insert(const string &s) {
    int u = 0;
    for (char c : s) {
        int v = c - 'a';
        if (!ch[u][v]) ch[u][v] = ++tot;
        u = ch[u][v];
    }
    endMark[u] = true;
}

bool search(const string &s) {
    int u = 0;
    for (char c : s) {
        int v = c - 'a';
        if (!ch[u][v]) return false;
        u = ch[u][v];
    }
    return endMark[u];
}

bool startsWith(const string &s) {
    int u = 0;
    for (char c : s) {
        int v = c - 'a';
        if (!ch[u][v]) return false;
        u = ch[u][v];
    }
    return true;
}

int main() {
    insert("apple");
    insert("app");
    insert("banana");
    insert("band");
    cout << "search apple: " << (search("apple") ? "是" : "否") << endl;
    cout << "search app: " << (search("app") ? "是" : "否") << endl;
    cout << "search appl: " << (search("appl") ? "是" : "否") << endl;
    cout << "startsWith app: " << (startsWith("app") ? "是" : "否") << endl;
    cout << "startsWith ban: " << (startsWith("ban") ? "是" : "否") << endl;
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
using namespace std;

vector<int> buildNext(const string &p) {
    int m = p.size();
    vector<int> nxt(m, 0);
    int j = 0;
    for (int i = 1; i < m; i++) {
        while (j > 0 && p[i] != p[j]) j = nxt[j-1];
        if (p[i] == p[j]) j++;
        nxt[i] = j;
    }
    return nxt;
}

vector<int> kmpSearch(const string &s, const string &p) {
    vector<int> nxt = buildNext(p);
    vector<int> result;
    int n = s.size(), m = p.size();
    int j = 0;
    for (int i = 0; i < n; i++) {
        while (j > 0 && s[i] != p[j]) j = nxt[j-1];
        if (s[i] == p[j]) j++;
        if (j == m) {
            result.push_back(i - m + 1);
            j = nxt[j-1];
        }
    }
    return result;
}

int main() {
    string s = "abababaababacaababaca";
    string p = "ababaca";
    vector<int> pos = kmpSearch(s, p);
    cout << "模式串: " << p << endl;
    cout << "文本串: " << s << endl;
    cout << "匹配位置: ";
    for (int x : pos) cout << x << " ";
    cout << endl;
    cout << "匹配次数: " << pos.size() << endl;
    return 0;
}
